#[must_use]
pub fn related_tests(paths: &[String], test_files: &[String], dirs: &[String]) -> Option<Vec<String>> {
    let pool: Vec<&String> = test_files
        .iter()
        .filter(|t| dirs.is_empty() || dirs.iter().any(|d| under(t, d)))
